 var ops=null;try{var raw=w.invOperationsCurrent(),expected=db.inventoryLink&&db.inventoryLink.siteId,scope=db.inventoryLink&&db.inventoryLink.accountScope;var demo=!!(ref.demo||db.exempleCharge);if(raw&&expected&&raw.establishment.id===expected&&(!raw.demo||demo)&&(!scope||raw.account&&raw.account.scope===scope)){ops=w.VerdictOperations.safeContext(raw);ops.demo=!!raw.demo;ops.stale=Date.now()-Date.parse(raw.generatedAt)>86400000;}}catch(e){}
 return {name:db.etab||'',structure:{ready:!!(R&&R.ready),score:R&&R.ready?Math.round(R.score):null,result:R&&R.ready?R.d.res:null,year:db.exerciseYear||(db.ref&&db.ref.exercice)||'',label:R&&R.ready?w.verdictScoreText('short',R,db):'',negative:!!(R&&R.ready&&R.d.res<0)},menu:{score:score&&score.available?score.total:null,period:ref.period||'',demo:!!ref.demo,estimated:!!ref.estimated,ready:!!ref.ready,missing:rows.filter(function(x){return !x.k||!x.k.complete;}).length,under:under,top:under[0]||null},inventory:{period:inv&&inv.m||'',ready:!!(analysis&&analysis.ready),consumed:analysis&&analysis.ready?analysis.conso:null,gap:comparable?analysis.theo.gap:null,comparable:comparable,ops:ops}};
