 if(i.ops)stock+='<p>'+i.ops.stock.critical+' '+text('critical')+'</p><p class="vg-meta">'+esc(i.ops.generated_at)+(i.ops.demo?' · '+text('demo'):'')+(i.ops.stale?' · '+text('stale'):'')+'</p>';
 stock+='<p class="vg-meta">'+text('noProof')+'</p>'+button(text('inventoryOpen'),'inventory')+'</article>';
