function mount(view){if(view!=='audit'&&view!=='dec')return;var root=d.getElementById('v-'+view);if(!root)return;root.classList.add('vg-active');var old=root.querySelector('[data-vg-summary]');if(old)old.remove();var box=d.createElement('div');box.innerHTML=html(view);var anchor=root.querySelector('.sub')||root.querySelector('h1');if(view==='audit'){var body=d.getElementById('auditBody');if(body)body.insertBefore(box.firstChild,body.firstChild);}else if(anchor)anchor.insertAdjacentElement('afterend',box.firstChild);else root.insertBefore(box.firstChild,root.firstChild);}
function action(type,id){var profiles=w.VerdictModuleProfilesV45;
 if(type==='inventory'){w.invOuvrirSource();return;}
 if(type==='menu'||type==='dish'){
  if(profiles)profiles.setProfile('carte',false);w.go('carte');if(type==='dish')w.VerdictCartePages.preview(id);else w.VerdictCartePages.open('plats');
  var pane=d.getElementById(type==='dish'?'c-sim':'c-plats');if(pane&&!pane.querySelector('[data-vg-action="audit"]'))pane.insertAdjacentHTML('afterbegin',button(text('back'),'audit'));return;
 }
 if(profiles)profiles.setProfile('pilotage',false);w.go(type==='audit'?'audit':type==='input'?'in':'dec');
}
function install(){
 if(w.__vgInstalled)return;w.__vgInstalled=true;
 var style=d.createElement('style');style.textContent='.vg-overview{margin:18px 0 24px;color:var(--txt);line-height:1.5}.vg-overview h2{font-size:24px;margin:0 0 6px}.vg-overview>p{margin:6px 0 14px}.vg-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.vg-card{border:1px solid rgba(127,127,127,.25);border-radius:20px;padding:18px;background:rgba(127,127,127,.075);color:inherit;min-width:0}.vg-card h3{display:flex;justify-content:space-between;gap:12px;font-size:18px;margin:0 0 12px}.vg-card p{font-size:16px;overflow-wrap:anywhere}.vg-card .btn{width:100%;white-space:normal;min-height:44px;margin-top:8px}.vg-meta,.vg-card p.vg-meta{color:var(--mut);font-size:14px}.vg-active>[data-chr-primary-view]{display:none!important}@media(max-width:800px){.vg-grid{grid-template-columns:1fr}}@media print{.vg-overview{display:block!important}.vg-overview button{display:none}.vg-card{break-inside:avoid}.vg-grid{display:block}}';d.head.appendChild(style);
 var go=w.go;w.go=function(view){var result=go.apply(this,arguments);if(result!==false)mount(view);return result;};
 ['drawAudit','drawDec'].forEach(function(name){var original=w[name];w[name]=function(){var r=original.apply(this,arguments);mount(name==='drawAudit'?'audit':'dec');return r;};});
 d.addEventListener('click',function(e){var b=e.target.closest('[data-vg-action]');if(b){e.preventDefault();action(b.getAttribute('data-vg-action'),b.getAttribute('data-vg-dish'));}});
 mount(w.VIEW);
}
w.VerdictConnectedAudit={snapshot:snapshot,html:html,action:action,mount:mount,copy:T};
if(d.readyState==='loading')d.addEventListener('DOMContentLoaded',install,{once:true});else install();
